    keys_seen = set()

    for node in nodes:
        for key, value in node.items():
            if key in result:
                if isinstance(result[key], MappingNode) and isinstance(value, MappingNode):
                    deep_merge_nodes([result[key], value])
                    result[key] = MappingNode(result[key])
                else:
                    result[key] = value
            else:
