    def absorb(self, args):
        absorbed = []
        for expr in args:
            if isinstance(expr, tuple) and len(expr) == 2 and isinstance(expr[0], str) and expr[0].isupper():
                operation, operand = expr
                if operation in ['AND', 'OR']:
                    if operand == True:
                        absorbed.append(True)
                    elif operand == False:
                        absorbed.append(False)
                    continue
            absorbed.append(expr)
        return absorbed

