class Registry:
    def __init__(self):
        self._hooks = {}

    def on(self, hook):
        def decorator(func):
            if hook not in self._hooks:
                self._hooks[hook] = []
            self._hooks[hook].append(func)
            return func
        return decorator

    def _call_hooks(self, func, hook):
        for h in self._hooks.get(hook, []):
            h(func)

    def __getattr__(self, hook):
        def handler(*args, **kwargs):
            self._call_hooks(handler, hook)
        return handler

registry = Registry()

