import zope.interface
from zope.interface import Invalid

def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []
    if not iface.provided_by(candidate):
        errors.append(zope.interface.Invalid(f"{candidate.__name__} does not provide {iface.__name__}"))
    elif not tentative:
        methods = iface.names()
        for method in methods:
            if not hasattr(candidate, method):
                errors.append(zope.interface.Invalid(f"{candidate.__name__} does not define method {method}"))
            elif not callable(getattr(candidate, method)):
                errors.append(zope.interface.Invalid(f"{candidate.__name__}'s method {method} is not callable"))
            elif vtype and not isinstance(getattr(candidate, method), vtype):
                errors.append(zope.interface.Invalid(f"{candidate.__name__}'s method {method} does not have the correct type"))
        attributes = iface.names(include_methods=False)
        for attr in attributes:
            if not hasattr(candidate, attr):
                errors.append(zope.interface.Invalid(f"{candidate.__name__} does not define attribute {attr}"))
            elif not isinstance(getattr(candidate, attr), iface.provided_by(candidate)):
                errors.append(zope.interface.Invalid(f"{candidate.__name__}'s attribute {attr} does not have the correct type"))

    if errors:
        raise Invalid(errors)
    return True

import inspect
from zope.interface import Interface, implementer, providedBy
from zope.interface.exceptions import Invalid

def verifyObject(iface, candidate, tentative=False):
    if not providedBy(candidate, iface) and not tentative:
        raise Invalid(f"{candidate} must provide {iface}")

    candidate_methods = {name: method for name, method in inspect.getmembers(candidate, predicate=inspect.isfunction)}
    required_methods = set(iface.methods())

    if not required_methods.issubset(candidate_methods.keys()):
        missing_methods = required_methods - set(candidate_methods.keys())
        raise Invalid(f"Candidate is missing methods: {missing_methods}")

    for method_name in candidate_methods:
        candidate_method = getattr(candidate, method_name)
        if_method = getattr(iface, method_name)

        if not callable(candidate_method):
            raise Invalid(f"{method_name} is not callable or not a method in {candidate}")

        if not if_method.isabstract:
            try:
                signature = inspect.signature(candidate_method)
                if_method.signature!= signature:
                    raise Invalid(f"Signature for {method_name} does not match: {signature}!= {if_method.signature}")
            except ValueError:
                raise Invalid(f"Signature for {method_name} could not be determined")

    required_attributes = set(iface.attributes())
    candidate_attributes = set(dir(candidate))

    if not required_attributes.issubset(candidate_attributes):
        missing_attributes = required_attributes - candidate_attributes
        raise Invalid(f"Candidate is missing attributes: {missing_attributes}")

    return True

class InterfaceVerifier:
    def verifyClass(self, iface, candidate, tentative=False):
        if not hasattr(candidate, '__dict__'):
            raise TypeError("Candidate must be a class.")

        required_methods = []
        for method in iface.__dict__.values():
            if callable(method) and not method.__name__.startswith('_'):
                # Check if method exists in candidate and has the same signature
                candidate_method = getattr(candidate, method.__name__, None)
                if not candidate_method or not callable(candidate_method):
                    required_methods.append(method.__name__)

        if required_methods:
            return False

        if tentative:
            return True

        # If no issues found and it's not tentative, return a confirmation
        return True

