import requests
from urllib.parse import urlparse

def get_nodeinfo_well_known_document(url, document_path=None):
    parsed_url = urlparse(url)
    nodeinfo_url = f"{parsed_url.scheme}://{parsed_url.netloc}/nodeinfo"

    try:
        response = requests.get(nodeinfo_url)
        response.raise_for_status()
        node_info = response.json()
        result = {
            "url": nodeinfo_url,
            "document_path": document_path if document_path else node_info.get("documentPath", "None provided"),
            "node_id": node_info.get("nodeId", "None provided"),
            "name": node_info.get("name", "None provided")
        }
        return result
    except requests.RequestException as e:
        return {"error": str(e)}

import json
from urllib.parse import urlparse, parse_qs

def parse_diaspora_webfinger(document: str) -> dict:
    webfinger_data = json.loads(document)
    hcard_url = webfinger_data.get('rel', {}).get('hcard', {}).get('href')

    if hcard_url:
        parsed_url = urlparse(hcard_url)
        query_params = parse_qs(parsed_url.query)
        # Assuming we want to extract the fragment if present
        fragment = query_params.get('fragment', [None])[0]
        return {'hcard_url': hcard_url, 'fragment': fragment}
    else:
        return {}

import requests
from typing import Optional

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    url = f"https://webfinger.net/{handle}?_format=application/jrd+json"
    try:
        response = requests.get(url)
        response.raise_for_status()  # Will raise an HTTPError if the HTTP request returned an unsuccessful status code
        return response.text
    except requests.RequestException:
        return None

import requests

class XRD:
    def __init__(self, data):
        self.data = data

def retrieve_diaspora_host_meta(host):
    response = requests.get(f"https://{host}/host_meta.xml")
    if response.status_code == 200:
        return XRD(response.text)
    else:
        raise Exception("Failed to retrieve host meta")
